configuration.jsScript:
var devName = metadata.deviceName != null ? metadata.deviceName.toString() : "";
var devType = metadata.deviceType != null ? metadata.deviceType.toString() : "";
var qStr = msg.quality != null ? msg.quality.toString().trim().toUpperCase() : "";

if (qStr.equals("BAD")) {
    var faultRoutes = ["Comm_Fault_Route"];
    if (devType.equals("Power_Meter")) {
        faultRoutes.add("Energy_Route");
        faultRoutes.add("Slave_Mirror_Route");
    }
    if (devType.equals("TK4S_Controller")) {
        faultRoutes.add("Slave_Mirror_Route");
    }
    if (devName.equals("ONSEN_PLC_MAIN") || devType.equals("PLC_Coordinator")) {
        faultRoutes.add("PLC_Demux_Route");
    }
    return faultRoutes;
}

if (devName.equals("ONSEN_PLC_MAIN") || devType.equals("PLC_Coordinator")) {
    var plcRoutes = ["PLC_Latest_Route", "Comm_Restored_Route"];
    var hasPtOrDi = (
        msg.PT100_CH01_BoiNong40 != null || msg.PT100_CH02_Jacuzzi35 != null || msg.PT100_CH03_BoiLanh28 != null ||
        msg.PT100_CH04_BoiLanh18_1 != null || msg.PT100_CH05_BoiLanh18_2 != null || msg.PT100_CH06_SaunaKho_1 != null ||
