// Standardize PLC / Modbus Communication Fault payload
var tsMs = metadata.ts != null ? Long.parseLong(metadata.ts.toString()) : System.currentTimeMillis();
var errStr = msg.errorReason != null ? msg.errorReason.toString().trim() : "GATEWAY_INACTIVITY_TIMEOUT";
if (errStr.isEmpty()) {
    errStr = "MODBUS_COMM_LOST";
}
var devName = metadata.deviceName != null ? metadata.deviceName.toString() : "Device";
var devType = metadata.deviceType != null ? metadata.deviceType.toString() : "Unknown";

var outMsg = {
    "quality": "BAD",
    "comm_status": "OFFLINE",
    "online": 0,
    "errorReason": errStr,
    "last_error_ts": tsMs,
    "alarmCode": "COMM_FAULT",
    "alarmLevel": "Mất kết nối PLC / Modbus - MAJOR - COMM_FAULT",
    "alarmNote": "Thiết bị " + devName + " (" + devType + ") mất kết nối phần cứng: " + errStr
};

// When a Power Meter is disconnected (CONNECT_FAILED / READ_FAILED), zero out live instantaneous power/current
// so SCADA screens never display frozen kW/A from days ago as live load!
if (devType.equals("Power_Meter")) {
    outMsg.p_total = 0.0;
    outMsg.q_total = 0.0;
    outMsg.s_total = 0.0;
    outMsg.p_a = 0.0;
    outMsg.p_b = 0.0;
    outMsg.p_c = 0.0;
    outMsg.i_a = 0.0;
    outMsg.i_b = 0.0;
    outMsg.i_c = 0.0;
    outMsg.i_total = 0.0;
}

return {msg: outMsg, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

