// 100% Soft-Configured Multi-Source Demultiplexer (Zero Hardcoded Channels)
// Reads station_io_matrix_json from ONSEN_PLC_MAIN SERVER_SCOPE attribute
var isPlcOff = (msg.quality != null && msg.quality.toString().toUpperCase().equals("BAD"));
var errStr = msg.errorReason != null ? msg.errorReason.toString() : "";
var fMask = msg.PT100_FAULT_MASK != null ? Integer.parseInt(msg.PT100_FAULT_MASK.toString()) : 0;
var diMask = msg.DI_BITMASK_16 != null ? Integer.parseInt(msg.DI_BITMASK_16.toString()) : -1;

var matrixRaw = metadata.ss_station_io_matrix_json;
if (matrixRaw == null || matrixRaw.toString().trim().isEmpty()) {
    return null;
}
var matrixObj = JSON.parse(matrixRaw.toString());
var zonesMap = matrixObj.zones;
if (zonesMap == null) {
    return null;
}

// Helper to read value from msg first, then metadata (latest telemetry on ONSEN_PLC_MAIN)
function getVal(key) {
    if (key == null || key.equals("NONE") || key.isEmpty()) return null;
    if (msg[key] != null) return msg[key];
    if (metadata[key] != null) return metadata[key];
    return null;
}

var outList = [];
foreach (zEntry : zonesMap.entrySet()) {
    var zCode = zEntry.getKey();
    var zCfg = zEntry.getValue();
    var astName = zCfg.assetName;
    if (astName == null || astName.toString().isEmpty()) continue;

    var zMsg = {};
    var touched = false;

    // 1. MULTI-SOURCE TEMPERATURE RESOLUTION (PT100 + TK4S Modbus + Offset + Fallback)
    var tCfg = zCfg.tempConfig != null ? zCfg.tempConfig : {};
    var tMode = tCfg.mode != null ? tCfg.mode.toString() : "AUTO_PT100_FIRST";
    var pt1Key = tCfg.pt100Primary != null ? tCfg.pt100Primary.toString() : "NONE";
    var pt2Key = tCfg.pt100Secondary != null ? tCfg.pt100Secondary.toString() : "NONE";
    var tkDev = tCfg.tk4sDevice != null ? tCfg.tk4sDevice.toString() : "NONE";
    var offsetC = tCfg.offsetC != null ? Double.parseDouble(tCfg.offsetC.toString()) : 0.0;
    var maxDiffC = tCfg.maxDiffWarnC != null ? Double.parseDouble(tCfg.maxDiffWarnC.toString()) : 2.5;

    var rawPt1 = getVal(pt1Key);
    var rawPt2 = getVal(pt2Key);
    var rawTkPv = (!tkDev.equals("NONE")) ? getVal(tkDev + "_PV") : null;
    var rawTkSv = (!tkDev.equals("NONE")) ? getVal(tkDev + "_SV") : null;
    var rawTkOk = (!tkDev.equals("NONE")) ? getVal(tkDev + "_OK") : null;

    var pt1Valid = (!isPlcOff && rawPt1 != null);
    var pt2Valid = (!isPlcOff && rawPt2 != null);
    var tkValid = (rawTkPv != null && (rawTkOk == null || !rawTkOk.toString().equals("0")));

    var ptVal = 0.0;
    if (pt1Valid) {
        ptVal = Double.parseDouble(rawPt1.toString());
        if (ptVal < -50.0 || ptVal > 250.0) { pt1Valid = false; }
    }
    var pt2Val = 0.0;
    if (pt2Valid) {
        pt2Val = Double.parseDouble(rawPt2.toString());
        if (pt2Val < -50.0 || pt2Val > 250.0) { pt2Valid = false; }
    }
    var tkVal = 0.0;
    if (tkValid) {
        tkVal = Double.parseDouble(rawTkPv.toString());
        if (tkVal < -50.0 || tkVal > 250.0) { tkValid = false; }
    }

    if (pt1Valid) { zMsg.temp_pt100 = Math.round((ptVal + offsetC) * 10.0) / 10.0; }
    if (pt2Valid) { zMsg.temperature_ch2 = Math.round((pt2Val + offsetC) * 10.0) / 10.0; }
    if (tkValid)  { zMsg.temp_tk4s = Math.round(tkVal * 10.0) / 10.0; }
    if (rawTkSv != null) { zMsg.tk4s_sv = Double.parseDouble(rawTkSv.toString()); }

    if (pt1Valid && tkValid) {
        var diff = Math.abs((ptVal + offsetC) - tkVal);
        zMsg.temp_diff = Math.round(diff * 10.0) / 10.0;
        zMsg.temp_drift_warn = (diff > maxDiffC) ? 1 : 0;
    }

    var finalT = null;
    var activeSrc = "NONE";

    if (tMode.equals("PT100_ONLY")) {
        if (pt1Valid) { finalT = ptVal + offsetC; activeSrc = "PT100 (" + pt1Key + ")"; }
    } else if (tMode.equals("TK4S_ONLY")) {
        if (tkValid) { finalT = tkVal + offsetC; activeSrc = "TK4S (" + tkDev + ")"; }
    } else if (tMode.equals("AUTO_TK4S_FIRST")) {
        if (tkValid) {
            finalT = tkVal + offsetC;
            activeSrc = "TK4S (" + tkDev + ")";
        } else if (pt1Valid) {
            finalT = ptVal + offsetC;
            activeSrc = "FALLBACK_PT100 (" + pt1Key + ")";
        }
    } else if (tMode.equals("AVERAGE_BOTH")) {
        if (pt1Valid && pt2Valid) {
            zMsg.temperature_ch1 = Math.round((ptVal + offsetC) * 10.0) / 10.0;
            finalT = ((ptVal + pt2Val) / 2.0) + offsetC;
            activeSrc = "AVG_PT100 (" + pt1Key + "+" + pt2Key + ")";
        } else if (pt1Valid && tkValid) {
            finalT = ((ptVal + tkVal) / 2.0) + offsetC;
            activeSrc = "AVG (PT100+" + tkDev + ")";
        } else if (pt1Valid) {
            finalT = ptVal + offsetC;
            activeSrc = "PT100 (" + pt1Key + ")";
        } else if (tkValid) {
            finalT = tkVal + offsetC;
            activeSrc = "TK4S (" + tkDev + ")";
        }
    } else {
        // Default: AUTO_PT100_FIRST
        if (pt1Valid) {
            finalT = ptVal + offsetC;
            activeSrc = "PT100 (" + pt1Key + ")";
        } else if (tkValid) {
            finalT = tkVal + offsetC;
            activeSrc = "FALLBACK_TK4S (" + tkDev + ")";
        }
    }

    // Supply pipe temperatures on Z05
    if (zCode.equals("Z05")) {
        var sup1 = getVal("PT100_CH11_CapNhiet_1");
        var sup2 = getVal("PT100_CH12_CapNhiet_2");
        if (sup1 != null) { zMsg.temp_supply_1 = Double.parseDouble(sup1.toString()); }
        if (sup2 != null) { zMsg.temp_supply_2 = Double.parseDouble(sup2.toString()); }
    }

    if (finalT != null) {
        zMsg.temperature = Math.round(finalT * 10.0) / 10.0;
        zMsg.temp_source_active = activeSrc;
        zMsg.quality = "GOOD";
        zMsg.comm_status = "ONLINE";
        zMsg.online = 1;
        zMsg.errorReason = "";
        touched = true;
    } else if (isPlcOff) {
        zMsg.quality = "BAD";
        zMsg.comm_status = "OFFLINE";
        zMsg.online = 0;
        zMsg.errorReason = errStr.isEmpty() ? "PLC_MODBUS_OFFLINE" : errStr;
        touched = true;
    }

    // 2. MULTI-SOURCE MACHINE STATUS RESOLUTION (DI + 3-Phase Power Inference + DO)
    var machines = zCfg.machines;
    if (machines != null && machines.size() > 0 && !isPlcOff) {
        var runCnt = 0;
        var totCnt = machines.size();
        for (var j = 0; j < totCnt; j++) {
            var m = machines[j];
            var sMode = m.statusMode != null ? m.statusMode.toString() : "HYBRID_DI_AND_POWER";
            var diK = m.diKey != null ? m.diKey.toString() : "NONE";
            var doK = m.doKey != null ? m.doKey.toString() : "NONE";
            var mDev = m.meterDevice != null ? m.meterDevice.toString() : "NONE";
            var ph = m.phase != null ? m.phase.toString() : "3P_COMBO";
            var thrKw = m.runThresholdKw != null ? Double.parseDouble(m.runThresholdKw.toString()) : 0.25;

            var diOn = false;
            if (!diK.equals("NONE")) {
                var dv = getVal(diK);
                if (dv != null) {
                    var ds = dv.toString().trim().toUpperCase();
                    diOn = (ds.equals("1") || ds.equals("1.0") || ds.equals("TRUE") || ds.equals("ON"));
                }
            }
            var doOn = false;
            if (!doK.equals("NONE")) {
                var dov = getVal(doK);
                if (dov != null) {
                    var dos = dov.toString().trim().toUpperCase();
                    doOn = (dos.equals("1") || dos.equals("1.0") || dos.equals("TRUE") || dos.equals("ON"));
                }
            }
            var pwrOn = false;
            if (!mDev.equals("NONE")) {
                var pKey = mDev + "_P";
                if (ph.equals("PHASE_A")) { pKey = mDev + "_PA"; }
                else if (ph.equals("PHASE_B")) { pKey = mDev + "_PB"; }
                else if (ph.equals("PHASE_C")) { pKey = mDev + "_PC"; }
                var pv = getVal(pKey);
                if (pv != null) {
                    var pKw = Double.parseDouble(pv.toString());
                    pwrOn = (pKw >= thrKw);
                }
            }

            var isMRun = false;
            if (sMode.equals("DI_ONLY")) {
                isMRun = diOn;
            } else if (sMode.equals("POWER_ONLY")) {
                isMRun = pwrOn;
            } else if (sMode.equals("DO_FEEDBACK")) {
                isMRun = doOn;
            } else {
                // HYBRID_DI_AND_POWER
                isMRun = (!diK.equals("NONE") && diOn) || pwrOn;
            }
            if (isMRun) {
                runCnt = runCnt + 1;
            }
        }
        zMsg.di_running_count = runCnt;
        zMsg.di_total_count = totCnt;
        zMsg.di_primary_status = runCnt > 0 ? "RUNNING" : "STANDBY";
        zMsg.status = runCnt > 0 ? "RUNNING" : "STANDBY";
        if (zMsg.quality == null) {
            zMsg.quality = "GOOD";
            zMsg.comm_status = "ONLINE";
            zMsg.online = 1;
            zMsg.errorReason = "";
        }
        touched = true;
    }

    if (touched) {
        var zMeta = {};
        foreach (k : metadata.keySet()) {
            zMeta[k] = metadata[k];
        }
        zMeta.targetAssetName = astName;
        zMeta.deviceName = astName;
        zMeta.deviceType = "Onsen_Zone";
        outList.add({msg: zMsg, metadata: zMeta, msgType: "POST_TELEMETRY_REQUEST"});
    }
}
return outList;

